/**
 * Shared renderer for any screen that's a flat list of heading+body sections — Terms & Conditions
 * and Privacy Policy (spec §3/§4), and the Tutorials hub's static articles (spec §6.1/§6.3/§6.4/
 * §6.5). Per-section string resources at each call site per the "legal text storage" decision (each
 * section its own resource, easy to diff/update independently; no precedent in this codebase for one
 * giant multi-paragraph string) — this composable just lays them out. Own `Scaffold`/`TopAppBar`
 * with a back button, same pattern as every other pushed (non-tab) destination.
 *
 * A section with a blank heading renders body-only (no heading row) — used for flowing-paragraph
 * content (e.g. §6.1) that doesn't have a natural per-paragraph heading, so callers don't need a
 * second shape just for that case.
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun DocumentSectionsScreen(
    title: String,
    sections: List<Pair<String, String>>,
    onNavigateUp: () -> Unit,
    lastUpdatedLabel: String? = null,
    showFooter: Boolean = false
) {
    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text(text = title) },
                navigationIcon = {
                    IconButton(onClick = onNavigateUp) {
                        Icon(
                            painter = painterResource(id = R.drawable.ic_back),
                            contentDescription = stringResource(id = R.string.nav_back_content_description)
                        )
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = MaterialTheme.colorScheme.background
                )
            )
        }
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
                .verticalScroll(rememberScrollState())
                .padding(dimensionResource(id = R.dimen.padding_large))
        ) {
            if (lastUpdatedLabel != null) {
                Text(
                    text = lastUpdatedLabel,
                    style = MaterialTheme.typography.bodySmall,
                    color = LocalPulseColors.current.onSurfaceMuted
                )
                Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_xlarge)))
            }

            sections.forEach { (heading, body) ->
                if (heading.isNotBlank()) {
                    Text(
                        text = heading,
                        style = MaterialTheme.typography.titleMedium.copy(fontWeight = FontWeight.Bold)
                    )
                    Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_small)))
                }
                Text(
                    text = body,
                    style = MaterialTheme.typography.bodyMedium
                )
                Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_xlarge)))
            }

            if (showFooter) {
                DisclaimerFooter()
            }
        }
    }
}
